def choose_next(cur, left, tau, eta, alpha, beta, rng):
    left = np.asarray(left)
    w = (tau[cur, left] ** alpha) * (eta[cur, left] ** beta)   # τ^α · η^β для кожного кандидата
    s = w.sum()
    p = w / s if s > 0 and np.isfinite(s) else np.full(len(left), 1 / len(left))
    return int(rng.choice(left, p=p))

