def update_pheromone(tau, tours, lens, rho):
    new = (1 - rho) * tau                                      # випаровування (нова матриця, tau не змінюємо)
    for t, L in zip(tours, lens):
        route = np.concatenate(([0], np.asarray(t, dtype=int), [0]))   # додаємо вокзал на початку і в кінці
        np.add.at(new, (route[:-1], route[1:]), 1.0 / L)       # ребро i→j поповнює tau[i, j]
    return new
